const saved=new Set(JSON.parse(localStorage.getItem('stridePrescribedResources')||'[]'));let activeTab='prescribed',activeFilter='all',currentResource=resources[0],currentResourceSource='prescribed',entryTotal=8;
function showScreen(id){document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.go===id));window.scrollTo({top:0,behavior:'instant'});if(id==='resources'){renderMyResources();renderLibrary()}}
document.querySelectorAll('.go').forEach(b=>b.addEventListener('click',()=>showScreen(b.dataset.go)));
function resourceMarkup(r,source='library'){return `<button class="resource-card card open-resource" data-id="${r.id}" data-source="${source}"><img src="${r.image}" alt="${r.title}"><div><h3>${r.title}</h3><p>${r.type==='exercise'?'Prescribed Exercise':r.type==='aftercare'?'Aftercare Guide':'Information Guide'}</p><div class="resource-meta">${r.frequency}</div><span class="resource-badge ${r.area.replace(/\s+/g,'-')}">${r.area}</span></div><span class="chevron">›</span></button>`}
function bindResourceButtons(){document.querySelectorAll('.open-resource').forEach(b=>b.addEventListener('click',()=>openResource(b.dataset.id,b.dataset.source||'library')))}
function renderMyResources(){const items=resources.filter(r=>saved.has(r.id));document.getElementById('myResourceList').innerHTML=items.length?items.map(r=>resourceMarkup(r,'prescribed')).join(''):`<div class="card" style="margin:14px 18px 0;padding:18px"><strong style="display:block;margin-bottom:6px;font-size:14px">No prescribed resources yet</strong><p style="margin:0;color:var(--muted);font-size:12.5px;line-height:1.5">Scan a QR code from your podiatrist to add your prescribed exercises and information guides.</p></div>`;bindResourceButtons()}
function renderLibrary(){const q=document.getElementById('resourceSearch').value.toLowerCase().trim();const items=resources.filter(r=>(activeFilter==='all'||r.type===activeFilter||r.area===activeFilter)&&(!q||r.title.toLowerCase().includes(q)||r.description.toLowerCase().includes(q)));document.getElementById('libraryList').innerHTML=items.map(r=>resourceMarkup(r,'library')).join('');bindResourceButtons()}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{activeTab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('prescribedPanel').classList.toggle('active',activeTab==='prescribed');document.getElementById('libraryPanel').classList.toggle('active',activeTab==='library');if(activeTab==='prescribed')renderMyResources();else renderLibrary()}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x.dataset.filter===activeFilter));renderLibrary()}));
document.getElementById('resourceSearch').addEventListener('input',renderLibrary);const categorySelect=document.getElementById('categorySelect');if(categorySelect){categorySelect.addEventListener('change',()=>{activeFilter=categorySelect.value;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x.dataset.filter===activeFilter));renderLibrary()})}
function openResource(id,source='library'){currentResource=resources.find(r=>r.id===id)||resources[0];currentResourceSource=source;detailImage.src=currentResource.image;detailTitle.textContent=currentResource.title;detailTag.textContent=currentResource.type==='exercise'?'Prescribed Exercise':currentResource.type==='aftercare'?'Aftercare Guide':'Information Guide';detailDescription.textContent=currentResource.description;doseSets.textContent=currentResource.sets;doseReps.textContent=currentResource.reps;doseFrequency.textContent=currentResource.frequency;setsInput.value=currentResource.sets;repsInput.value=currentResource.reps;frequencyInput.value=currentResource.frequency;saveResource.textContent=currentResourceSource==='library'?'Back to Library':(saved.has(currentResource.id)?'Update Prescribed Resource':'Update Prescribed Resource');showScreen('detail')}
document.getElementById('saveResource').addEventListener('click',()=>{if(currentResourceSource==='library'){showScreen('resources');activeTab='library';document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='library'));document.getElementById('prescribedPanel').classList.remove('active');document.getElementById('libraryPanel').classList.add('active');renderLibrary();return;}currentResource.sets=setsInput.value;currentResource.reps=repsInput.value;currentResource.frequency=frequencyInput.value;doseSets.textContent=currentResource.sets;doseReps.textContent=currentResource.reps;doseFrequency.textContent=currentResource.frequency;saveResource.textContent='Prescribed Resource Updated'});

const modal=document.getElementById('progressModal');
const openProgressModal=()=>modal.classList.add('open');
newEntry.addEventListener('click',openProgressModal);
newEntryTop.addEventListener('click',openProgressModal);
document.querySelector('.close-progress').addEventListener('click',()=>modal.classList.remove('open'));document.querySelector('.close-progress').addEventListener('touchend',e=>{e.preventDefault();modal.classList.remove('open')},{passive:false});
modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open')});
let selectedPain=5,selectedImprovement=40;
document.querySelectorAll('#painChoices .number-choice').forEach(b=>b.addEventListener('click',()=>{selectedPain=Number(b.dataset.value);document.querySelectorAll('#painChoices .number-choice').forEach(x=>x.classList.toggle('selected',x===b))}));
document.querySelectorAll('#improvementChoices .percent-choice').forEach(b=>b.addEventListener('click',()=>{selectedImprovement=Number(b.dataset.value);document.querySelectorAll('#improvementChoices .percent-choice').forEach(x=>x.classList.toggle('selected',x===b))}));
document.querySelectorAll('[data-group]').forEach(group=>group.querySelectorAll('.pill-choice').forEach(b=>b.addEventListener('click',()=>group.querySelectorAll('.pill-choice').forEach(x=>x.classList.toggle('selected',x===b)))));
document.querySelector('#painChoices [data-value="5"]').classList.add('selected');
document.querySelector('#improvementChoices [data-value="40"]').classList.add('selected');
function selectedValue(group){return document.querySelector(`[data-group="${group}"] .selected`)?.dataset.value||''}
let latestCheckin={pain:5,morning:'Better',walking:'Better',shoes:'Same',flare:'No',consistency:'Mostly',improvement:40,better:'Morning stiffness has reduced and walking is more comfortable.',limited:'Stairs remain uncomfortable.'};
saveEntry.addEventListener('click',()=>{const morning=selectedValue('morning'),walking=selectedValue('walking'),shoes=selectedValue('shoes'),flare=selectedValue('flare'),consistency=selectedValue('consistency'),better=betterInput.value.trim(),limited=limitedInput.value.trim();entryTotal++;latestCheckin={pain:selectedPain,morning,walking,shoes,flare,consistency,improvement:selectedImprovement,better,limited};const date=new Date().toLocaleDateString('en-NZ',{day:'numeric',month:'long',year:'numeric'});const cls=v=>v==='Same'?'same':v==='Worse'?'worse':'';const card=document.createElement('div');card.className='history-card card';card.innerHTML=`<div class="history-top"><span class="history-date"><strong>${date}</strong></span><span class="pain-pill">Pain ${selectedPain}/10</span></div><div class="history-metrics"><div class="history-metric"><span>Morning</span><strong class="${cls(morning)}">${morning}</strong></div><div class="history-metric"><span>Walking</span><strong class="${cls(walking)}">${walking}</strong></div><div class="history-metric"><span>Shoes</span><strong class="${cls(shoes)}">${shoes}</strong></div></div>${better?`<div class="history-line"><strong>Better:</strong> ${better}</div>`:''}${limited?`<div class="history-line"><strong>Still limited:</strong> ${limited}</div>`:''}`;checkinHistory.prepend(card);betterInput.value='';limitedInput.value='';modal.classList.remove('open');updateSummaryModal()});if(window.copySummary&&window.podSummaryText){copySummary.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(podSummaryText.textContent);copySummary.textContent='Copied';setTimeout(()=>copySummary.textContent='Copy Summary',1500)}catch(e){alert(podSummaryText.textContent)}});}
if(window.shareSummary&&window.podSummaryText){shareSummary.addEventListener('click',async()=>{const txt=podSummaryText.textContent;if(navigator.share){try{await navigator.share({title:'Stride Progress Summary',text:txt})}catch(e){}}else{try{await navigator.clipboard.writeText(txt);alert('Progress summary copied.')}catch(e){alert(txt)}}});}


const summaryModal=document.getElementById('summaryModal');
function updateSummaryModal(){const c=latestCheckin;summaryLatestPain.textContent=`${c.pain}/10`;summaryImprovement.textContent=`${c.improvement}%`;summaryConsistency.textContent=c.consistency;const widths={Always:100,Mostly:82,Sometimes:55,Rarely:25};summaryConsistencyBar.style.width=(widths[c.consistency]||60)+'%';summaryConsistencyNote.textContent=c.consistency==='Always'?'Excellent consistency — you are completing your exercises very regularly.':c.consistency==='Mostly'?'You have been consistent with most prescribed exercises. Keep building on this routine.':c.consistency==='Sometimes'?'You are completing some exercises. A more regular routine may help support progress.':'Exercise consistency has been limited. Discuss any barriers with your podiatrist.';const readable=v=>v==='Better'?'Improving':v==='Worse'?'More limited':'About the same';summaryMorning.textContent=readable(c.morning);summaryWalking.textContent=readable(c.walking);summaryShoes.textContent=readable(c.shoes);summaryFlares.textContent=c.flare==='Yes'?'Flare-ups reported':'None reported';summaryNarrative.textContent=`${c.better?'What feels better: '+c.better+'. ':''}${c.limited?'What still feels limited: '+c.limited+'. ':''}Pain is currently ${c.pain}/10 and overall improvement is estimated at ${c.improvement}%.`;}
openSummary.addEventListener('click',()=>{updateSummaryModal();summaryModal.classList.add('open')});document.querySelector('.close-summary').addEventListener('click',()=>summaryModal.classList.remove('open'));summaryModal.addEventListener('click',e=>{if(e.target===summaryModal)summaryModal.classList.remove('open')});
function summaryText(){const c=latestCheckin;return `Stride progress summary: pain ${c.pain}/10; overall improvement ${c.improvement}%; exercise consistency ${c.consistency.toLowerCase()}; morning stiffness ${c.morning.toLowerCase()}; walking tolerance ${c.walking.toLowerCase()}; shoe comfort ${c.shoes.toLowerCase()}; flare-ups ${c.flare.toLowerCase()}. ${c.better?'Better: '+c.better+'. ':''}${c.limited?'Still limited: '+c.limited+'.':''}`}
copyProgressSummary.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(summaryText());copyProgressSummary.textContent='Copied';setTimeout(()=>copyProgressSummary.textContent='Copy Summary',1200)}catch(e){alert(summaryText())}});shareProgressSummary.addEventListener('click',async()=>{const t=summaryText();if(navigator.share){try{await navigator.share({title:'Stride Progress Summary',text:t})}catch(e){}}else{try{await navigator.clipboard.writeText(t);alert('Summary copied.')}catch(e){alert(t)}}});

const journeyStages=[
{name:'Getting Started',weeks:'Weeks 1–4',description:'Your initial assessment and initial adjustment are complete. Early FMT sessions focus on loosening restrictions and helping the foot and ankle joints move more freely.',fmt:'Loosen restrictions and begin getting the foot and ankle joints moving.',patient:'Complete prescribed exercises, attend FMT consistently, and notice patterns in symptoms and activity.',milestone:'Initial assessment and initial adjustment completed.',note:'You have taken the first important step. Focus on consistency and noticing how your movement responds.'},
{name:'Foundation Phase',weeks:'Weeks 5–8',description:'After your progress review, FMT usually becomes less frequent while the changes made during the first month are reinforced.',fmt:'Maintain changes, keep joints mobile, introduce strengthening, and target surrounding structures.',patient:'Continue prescribed exercises and stay consistent with appointments and healthy movement habits.',milestone:'Progress Review completed around Week 5 and your plan updated.',note:'Keep going — the changes you are building now support stronger, more comfortable movement.'},
{name:'Maintenance Phase',weeks:'Weeks 9–13',description:'Regular FMT sessions are gradually reduced while your podiatrist checks that movement is holding and there is no regression.',fmt:'Wean from regular FMT, monitor for regression, and build self-management tools.',patient:'Keep up prescribed exercises, use your self-management tools, and attend planned reviews.',milestone:'90-day review completed and long-term recommendations confirmed.',note:'You are building the confidence and tools to maintain your progress more independently.'},
{name:'Ongoing Support',weeks:'After 90 days',description:'The structured phase is complete and you are ready to self-manage, with support available when you need it.',fmt:'Periodic review of movement, symptoms, exercises, and any new concerns.',patient:'Continue exercises and arrange a review if symptoms change. Many patients prefer an FMT check every 6–12 months.',milestone:'Maintaining progress independently without regular sessions.',note:'Keep using the tools that help you move well, with periodic support when needed.'}
];
let currentStage=Math.min(3,Math.max(0,Number(localStorage.getItem('strideJourneyStage')||0)));
function renderJourneyPhases(){const phaseList=document.getElementById('journeyPhaseList');if(!phaseList)return;phaseList.innerHTML=journeyStages.map((stage,i)=>{const selected=i===currentStage;return `<article class="phase-card ${selected?'current open':''}" data-stage="${i}"><button class="phase-header" type="button"><span class="phase-icon">${selected?icons.check:String(i+1)}</span><span><span class="phase-weeks">${stage.weeks}</span><span class="phase-title">${stage.name}</span></span><span class="phase-status">${selected?'Current':'Select'}</span></button><div class="phase-details"><p>${stage.description}</p><div class="detail-row"><strong>FMT focus</strong><span>${stage.fmt}</span></div><div class="detail-row"><strong>Your focus</strong><span>${stage.patient}</span></div><div class="detail-row"><strong>Milestone</strong><span>${stage.milestone}</span></div><button class="btn secondary phase-select" type="button" data-select-stage="${i}">${selected?'Current phase':'Set as current phase'}</button></div></article>`}).join('');phaseList.querySelectorAll('.phase-header').forEach(btn=>btn.addEventListener('click',()=>btn.closest('.phase-card').classList.toggle('open')));phaseList.querySelectorAll('[data-select-stage]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();setJourneyStage(Number(btn.dataset.selectStage));}))}
function setJourneyStage(index){currentStage=Math.min(3,Math.max(0,Number(index)||0));localStorage.setItem('strideJourneyStage',String(currentStage));const s=journeyStages[currentStage];const homeStageLabel=document.getElementById('homeStageLabel');if(homeStageLabel)homeStageLabel.textContent=s.name;const homeStageNote=document.getElementById('homeStageNote');if(homeStageNote)homeStageNote.textContent=s.note;const onboardStageEl=document.getElementById('onboardStage');if(onboardStageEl)onboardStageEl.value=String(currentStage);renderJourneyPhases()}
setJourneyStage(currentStage);

let slideIndex=0;
let onboardingPain=null;
const onboardingEl=document.getElementById('onboarding');
const slidesEl=document.getElementById('slides');
const startOnboardingButton=document.getElementById('startOnboarding');
const finishOnboardingButton=document.getElementById('finishOnboarding');
function moveSlide(i){slideIndex=i;if(slidesEl)slidesEl.style.transform=`translateX(-${i*100}%)`}
function saveOnboardingDetails(){const name=(document.getElementById('onboardName')?.value||'').trim();const goal=(document.getElementById('onboardGoal')?.value||'').trim();const stage=Number(document.getElementById('onboardStage')?.value||0);if(name){localStorage.setItem('strideProfilePreferredName',name);localStorage.setItem('strideProfileName',name)}localStorage.setItem('strideJourneyStage',String(stage));if(goal)localStorage.setItem('strideGoal',goal);if(onboardingPain!==null)localStorage.setItem('strideInitialPain',String(onboardingPain));setJourneyStage(stage);loadOnboardingData();updateHomeGreeting();}
function completeOnboarding(){saveOnboardingDetails();localStorage.setItem('strideOnboardingComplete','true');onboardingEl?.classList.add('hidden')}
if(localStorage.getItem('strideOnboardingComplete')==='true'){onboardingEl?.classList.add('hidden')}
if(startOnboardingButton)startOnboardingButton.addEventListener('click',()=>moveSlide(1));
const continueToSetupButton=document.getElementById('continueToSetup');if(continueToSetupButton)continueToSetupButton.addEventListener('click',()=>moveSlide(2));
const skipPatientIntroButton=document.getElementById('skipPatientIntro');if(skipPatientIntroButton)skipPatientIntroButton.addEventListener('click',()=>moveSlide(2));
document.querySelectorAll('.onboard-next').forEach(b=>b.addEventListener('click',()=>{saveOnboardingDetails();moveSlide(Number(b.dataset.nextStep))}));
document.querySelectorAll('[data-back-step]').forEach(b=>b.addEventListener('click',()=>moveSlide(Number(b.dataset.backStep))));
document.querySelectorAll('[data-onboard-intent]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-onboard-intent]').forEach(x=>x.classList.toggle('selected',x===b));localStorage.setItem('strideOnboardingIntent',b.dataset.onboardIntent)}));
document.querySelectorAll('[data-onboard-pain]').forEach(b=>b.addEventListener('click',()=>{onboardingPain=Number(b.dataset.onboardPain);document.querySelectorAll('[data-onboard-pain]').forEach(x=>x.classList.toggle('selected',x===b));onboardPainSelected.textContent=`Selected: ${onboardingPain}/10`}));
document.getElementById('onboardScanQr').addEventListener('click',()=>{document.getElementById('scanModal').classList.add('open')});
document.getElementById('onboardCreateAccount').addEventListener('click',()=>{saveOnboardingDetails();openAccountModal('create')});
if(finishOnboardingButton)finishOnboardingButton.addEventListener('click',completeOnboarding);

const accountModal=document.getElementById('accountModal');const resetPasswordModal=document.getElementById('resetPasswordModal');const authFeedback=document.getElementById('authFeedback');
function openAccountModal(tab='signin'){accountModal.classList.add('open');setAuthTab(tab)}function closeAccountModal(){accountModal.classList.remove('open');authFeedback.textContent='';authFeedback.className='auth-feedback'}
function setAuthTab(tab){document.querySelectorAll('.auth-tab').forEach(b=>b.classList.toggle('active',b.dataset.authTab===tab));signinPanel.classList.toggle('active',tab==='signin');createPanel.classList.toggle('active',tab==='create');accountModalTitle.textContent=tab==='signin'?'Sign in to Stride':'Create your Stride account';authFeedback.textContent='';authFeedback.className='auth-feedback'}
const existingAccountButton=document.getElementById('accountLink');if(existingAccountButton){existingAccountButton.addEventListener('click',()=>openAccountModal('signin'))}document.querySelectorAll('.auth-tab').forEach(b=>b.addEventListener('click',()=>setAuthTab(b.dataset.authTab)));document.querySelector('.close-account').addEventListener('click',closeAccountModal);accountModal.addEventListener('click',e=>{if(e.target===accountModal)closeAccountModal()});
function updateAccountStatus(){const email=localStorage.getItem('strideAccountEmail');const status=document.getElementById('accountStatus');if(status)status.textContent=email?`Signed in as ${email}`:'No account is currently signed in on this device.'}
function validPassword(value){return value.length>=8}
createAccountButton.addEventListener('click',()=>{const first=createFirstName.value.trim(),last=createLastName.value.trim(),preferred=createPreferredName.value.trim(),email=createEmail.value.trim().toLowerCase(),password=createPassword.value,confirm=createPasswordConfirm.value;if(!first||!last||!email){authFeedback.textContent='Please enter your first name, last name and email.';authFeedback.className='auth-feedback error';return}if(!validPassword(password)){authFeedback.textContent='Password must be at least 8 characters.';authFeedback.className='auth-feedback error';return}if(password!==confirm){authFeedback.textContent='Passwords do not match.';authFeedback.className='auth-feedback error';return}localStorage.setItem('strideAccountEmail',email);localStorage.setItem('strideAccountPassword',password);localStorage.setItem('strideProfileFirstName',first);localStorage.setItem('strideProfileLastName',last);localStorage.setItem('strideProfilePreferredName',preferred);localStorage.setItem('strideProfileName',preferred||first);localStorage.setItem('strideProfileEmail',email);localStorage.setItem('strideOnboardingComplete','true');localStorage.setItem('strideSignedIn','true');loadProfile();updateHomeGreeting();updateAccountStatus();authFeedback.textContent='Account created and signed in.';authFeedback.className='auth-feedback success';setTimeout(()=>{closeAccountModal();onboardingEl?.classList.add('hidden')},700)});
signinButton.addEventListener('click',()=>{const email=signinEmail.value.trim().toLowerCase(),password=signinPassword.value;const storedEmail=(localStorage.getItem('strideAccountEmail')||'').toLowerCase(),storedPassword=localStorage.getItem('strideAccountPassword')||'';if(!email||!password){authFeedback.textContent='Please enter your email and password.';authFeedback.className='auth-feedback error';return}if(!storedEmail){authFeedback.textContent='No Stride account has been created on this device yet. Choose Create account to set one up.';authFeedback.className='auth-feedback error';return}if(email!==storedEmail||password!==storedPassword){authFeedback.textContent='Email or password is incorrect.';authFeedback.className='auth-feedback error';return}localStorage.setItem('strideOnboardingComplete','true');localStorage.setItem('strideSignedIn','true');authFeedback.textContent='Signed in successfully.';authFeedback.className='auth-feedback success';updateAccountStatus();setTimeout(()=>{closeAccountModal();if(window.onboardingEl){onboardingEl.classList.add('hidden')}else{document.getElementById('onboarding')?.classList.add('hidden')}showScreen('home')},500)});signinPassword.addEventListener('keydown',e=>{if(e.key==='Enter')signinButton.click()});
updateAccountStatus();
resetPasswordButton.addEventListener('click',()=>{resetPasswordModal.classList.add('open');resetPasswordFeedback.textContent='';newPassword.value='';newPasswordConfirm.value=''});document.querySelector('.close-reset-password').addEventListener('click',()=>resetPasswordModal.classList.remove('open'));resetPasswordModal.addEventListener('click',e=>{if(e.target===resetPasswordModal)resetPasswordModal.classList.remove('open')});saveNewPassword.addEventListener('click',()=>{if(!localStorage.getItem('strideAccountEmail')){resetPasswordFeedback.textContent='Create an account before setting a password.';resetPasswordFeedback.className='auth-feedback error';return}if(!validPassword(newPassword.value)){resetPasswordFeedback.textContent='Password must be at least 8 characters.';resetPasswordFeedback.className='auth-feedback error';return}if(newPassword.value!==newPasswordConfirm.value){resetPasswordFeedback.textContent='Passwords do not match.';resetPasswordFeedback.className='auth-feedback error';return}localStorage.setItem('strideAccountPassword',newPassword.value);resetPasswordFeedback.textContent='Password updated.';resetPasswordFeedback.className='auth-feedback success';setTimeout(()=>resetPasswordModal.classList.remove('open'),700)});


const signOutButton=document.getElementById('signOutButton');if(signOutButton){signOutButton.addEventListener('click',()=>{localStorage.removeItem('strideSignedIn');showScreen('home');openAccountModal('signin');authFeedback.textContent='You have been signed out.';authFeedback.className='auth-feedback success';updateAccountStatus()})}

const scanModal=document.getElementById('scanModal');
const scannerVideo=document.getElementById('scannerVideo');
const scanStatusText=document.getElementById('scanStatusText');
const scanStatus=document.getElementById('scanStatus');
const manualCodeInput=document.getElementById('manualCodeInput');
let scanStream=null, scanTimer=null, barcodeDetector=null;
function openScanModal(){scanModal.classList.add('open')}
function closeScanModal(){stopScanner();scanModal.classList.remove('open')}
document.getElementById('openScanner').addEventListener('click',openScanModal);
document.querySelector('.close-scan').addEventListener('click',closeScanModal);
scanModal.addEventListener('click',e=>{if(e.target===scanModal)closeScanModal()});
function normalizeCode(raw=''){return raw.toLowerCase().trim().replace(/^resource:/,'').replace(/^stride:/,'')}
function completeScan(raw){const code=normalizeCode(raw);const item=resources.find(r=>r.id===code);if(!item){scanStatusText.textContent='Code not recognised. Try another QR code or enter a demo code manually.';return}saved.add(item.id);localStorage.setItem('stridePrescribedResources',JSON.stringify([...saved]));renderMyResources();scanStatus.textContent=`Added ${item.title} to My Resources.`;scanStatusText.textContent=`Added ${item.title}. You can scan another code or close this window.`;manualCodeInput.value='';stopScanner()}
async function startScanner(){scanStatusText.textContent='Starting camera…';if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){scanStatusText.textContent='Camera scanning is not supported on this device. Enter a code manually below.';return}try{scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});scannerVideo.srcObject=scanStream;await scannerVideo.play();if('BarcodeDetector' in window){barcodeDetector=new BarcodeDetector({formats:['qr_code']});scanStatusText.textContent='Point your camera at a QR code.';scanTimer=setInterval(async()=>{try{const codes=await barcodeDetector.detect(scannerVideo);if(codes&&codes.length){completeScan(codes[0].rawValue||'')}}catch(err){}},700)}else{scanStatusText.textContent='Live QR detection is not supported here. You can still enter the code manually below.'}}catch(err){scanStatusText.textContent='Camera access was unavailable. Please allow camera access or enter the code manually.'}}
function stopScanner(){if(scanTimer){clearInterval(scanTimer);scanTimer=null}if(scanStream){scanStream.getTracks().forEach(t=>t.stop());scanStream=null}if(scannerVideo.srcObject)scannerVideo.srcObject=null}
document.getElementById('startScannerBtn').addEventListener('click',startScanner);
document.getElementById('stopScannerBtn').addEventListener('click',()=>{stopScanner();scanStatusText.textContent='Scanner stopped.'});
document.getElementById('addManualCode').addEventListener('click',()=>completeScan(manualCodeInput.value));
manualCodeInput.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();completeScan(manualCodeInput.value)}});

