const motivationText=document.getElementById('motivationText');
const motivationSubtext=document.getElementById('motivationSubtext');
const motivationBanner=document.getElementById('motivationBanner');
const dismissMotivation=document.getElementById('dismissMotivation');
const today=new Date();const dayKey=Math.floor(Date.UTC(today.getFullYear(),today.getMonth(),today.getDate())/86400000);const todaysMessage=motivationMessages[dayKey%motivationMessages.length];
