function updateHomeGreeting(){
  const hour=new Date().getHours();
  const greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';
  const savedName=(localStorage.getItem('strideProfilePreferredName')||localStorage.getItem('strideProfileFirstName')||localStorage.getItem('strideProfileName')||'Alex').trim()||'Alex';
  const firstName=savedName.split(/\s+/)[0];
  const greetingEl=document.getElementById('timeGreeting');
  const nameEl=document.getElementById('homeFirstName');
  if(greetingEl&&nameEl){greetingEl.childNodes[0].nodeValue=greeting+',';nameEl.textContent=firstName;}
}
updateHomeGreeting();
function loadOnboardingData(){const goal=localStorage.getItem('strideGoal')||'Move more comfortably and confidently.';const pain=localStorage.getItem('strideInitialPain');['progressGoalText','journeyGoalText'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=goal});const painEl=document.getElementById('progressInitialPain');if(painEl)painEl.textContent=pain!==null?`${pain}/10`:'Not recorded';const name=localStorage.getItem('strideProfilePreferredName')||localStorage.getItem('strideProfileName')||'';const onboardName=document.getElementById('onboardName');if(onboardName&&!onboardName.value)onboardName.value=name;const onboardGoal=document.getElementById('onboardGoal');if(onboardGoal&&!onboardGoal.value&&localStorage.getItem('strideGoal'))onboardGoal.value=localStorage.getItem('strideGoal');const onboardStage=document.getElementById('onboardStage');if(onboardStage)onboardStage.value=localStorage.getItem('strideJourneyStage')||'0';}
loadOnboardingData();
const profileFirstName=document.getElementById('profileFirstName');const profileLastName=document.getElementById('profileLastName');const profilePreferredName=document.getElementById('profilePreferredName');const profileEmail=document.getElementById('profileEmail');
function loadProfile(){if(!profileFirstName)return;profileFirstName.value=localStorage.getItem('strideProfileFirstName')||'';profileLastName.value=localStorage.getItem('strideProfileLastName')||'';profilePreferredName.value=localStorage.getItem('strideProfilePreferredName')||localStorage.getItem('strideProfileName')||'Alex';profileEmail.value=localStorage.getItem('strideProfileEmail')||'';}
function saveProfileDetails(){localStorage.setItem('strideProfileFirstName',profileFirstName.value.trim());localStorage.setItem('strideProfileLastName',profileLastName.value.trim());localStorage.setItem('strideProfilePreferredName',profilePreferredName.value.trim());localStorage.setItem('strideProfileName',profilePreferredName.value.trim()||profileFirstName.value.trim()||'Alex');localStorage.setItem('strideProfileEmail',profileEmail.value.trim());document.getElementById('profileFeedback').textContent='Profile saved on this device.';updateHomeGreeting();updateAccountStatus();}
loadProfile();if(document.getElementById('saveProfile'))document.getElementById('saveProfile').addEventListener('click',saveProfileDetails);
document.querySelectorAll('.toggle[data-setting]').forEach(toggle=>{const key='strideSetting-'+toggle.dataset.setting;const stored=localStorage.getItem(key);if(stored!==null)toggle.classList.toggle('on',stored==='true');toggle.addEventListener('click',()=>{toggle.classList.toggle('on');localStorage.setItem(key,toggle.classList.contains('on'));});});
const clinicUpdatesToggle=document.getElementById('clinicUpdatesToggle');const exerciseRemindersToggle=document.getElementById('exerciseRemindersToggle');const progressRemindersToggle=document.getElementById('progressRemindersToggle');const exerciseReminderOptions=document.getElementById('exerciseReminderOptions');const progressReminderOptions=document.getElementById('progressReminderOptions');const exerciseTimeOne=document.getElementById('exerciseTimeOne');const exerciseTimeTwo=document.getElementById('exerciseTimeTwo');const exerciseTimeTwoField=document.getElementById('exerciseTimeTwoField');const exerciseTimeOneLabel=document.getElementById('exerciseTimeOneLabel');const progressReminderTime=document.getElementById('progressReminderTime');const notificationFeedback=document.getElementById('notificationFeedback');
if(clinicUpdatesToggle){if(localStorage.getItem('strideSetting-clinic-updates')===null){localStorage.setItem('strideSetting-clinic-updates','true');clinicUpdatesToggle.classList.add('on')}}
function showNotificationSaved(){if(!notificationFeedback)return;notificationFeedback.textContent='Notification preferences saved on this device.';clearTimeout(window.__notificationSavedTimer);window.__notificationSavedTimer=setTimeout(()=>notificationFeedback.textContent='',1800)}
function syncNotificationPanels(){if(exerciseReminderOptions)exerciseReminderOptions.classList.toggle('hidden',!exerciseRemindersToggle.classList.contains('on'));if(progressReminderOptions)progressReminderOptions.classList.toggle('hidden',!progressRemindersToggle.classList.contains('on'))}
[clinicUpdatesToggle,exerciseRemindersToggle,progressRemindersToggle].filter(Boolean).forEach(t=>t.addEventListener('click',()=>{syncNotificationPanels();showNotificationSaved()}));
let reminderCount=Number(localStorage.getItem('strideExerciseReminderCount')||'1');
function applyReminderCount(count){reminderCount=count;document.querySelectorAll('[data-reminder-count]').forEach(b=>b.classList.toggle('active',Number(b.dataset.reminderCount)===count));if(exerciseTimeTwoField)exerciseTimeTwoField.classList.toggle('hidden',count!==2);if(exerciseTimeOneLabel)exerciseTimeOneLabel.textContent=count===2?'Morning reminder':'Reminder time';localStorage.setItem('strideExerciseReminderCount',String(count))}
document.querySelectorAll('[data-reminder-count]').forEach(b=>b.addEventListener('click',()=>{applyReminderCount(Number(b.dataset.reminderCount));showNotificationSaved()}));
if(exerciseTimeOne){exerciseTimeOne.value=localStorage.getItem('strideExerciseTimeOne')||'08:00';exerciseTimeOne.addEventListener('change',()=>{localStorage.setItem('strideExerciseTimeOne',exerciseTimeOne.value);showNotificationSaved()})}
if(exerciseTimeTwo){exerciseTimeTwo.value=localStorage.getItem('strideExerciseTimeTwo')||'19:00';exerciseTimeTwo.addEventListener('change',()=>{localStorage.setItem('strideExerciseTimeTwo',exerciseTimeTwo.value);showNotificationSaved()})}
if(progressReminderTime){progressReminderTime.value=localStorage.getItem('strideProgressReminderTime')||'18:00';progressReminderTime.addEventListener('change',()=>{localStorage.setItem('strideProgressReminderTime',progressReminderTime.value);showNotificationSaved()})}
applyReminderCount(reminderCount);syncNotificationPanels();
document.querySelectorAll('.text-size-button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.text-size-button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.documentElement.style.fontSize=btn.dataset.size==='large'?'18px':btn.dataset.size==='small'?'14px':'16px';localStorage.setItem('strideTextSize',btn.dataset.size);}));
