function applyLanguage(code){const s=languageStrings[code]||languageStrings.en;document.documentElement.lang=code==='zh'?'zh-CN':code==='hi'?'hi-IN':code==='es'?'es':code;document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(s[k])el.textContent=s[k]});const w=document.getElementById('welcomeTitle');if(w)w.textContent=s.welcome;const a=document.getElementById('accountLink');if(a)a.textContent=s.account;const h=document.getElementById('languageHeading');if(h)h.textContent=s.language;const l=document.getElementById('languageLabel');if(l)l.textContent=s.appLanguage;const n=document.getElementById('languageNote');if(n)n.textContent=s.languageNote;localStorage.setItem('strideLanguage',code);const sel=document.getElementById('languageSelect');if(sel)sel.value=code}
const languageSelect=document.getElementById('languageSelect');if(languageSelect){const savedLanguage=localStorage.getItem('strideLanguage')||'en';languageSelect.value=savedLanguage;applyLanguage(savedLanguage);languageSelect.addEventListener('change',()=>applyLanguage(languageSelect.value));}

